#!/bin/bash
[ "$1" = "--version" ] && { echo "NET-SNMP version: 5.9.3"; exit 0; }
root="${!#}"
case "$MODE" in
  ok)      echo ".1.3.6.1.2.1.1.1.0 = STRING: x"; exit 0 ;;
  partial) echo ".1.3.6.1.2.1.1.1.0 = STRING: x"
           echo "Timeout: No Response from 1.2.3.4" >&2; exit 1 ;;
  dead)    echo "Timeout: No Response from 1.2.3.4" >&2; exit 1 ;;
  empty)   exit 0 ;;
esac

