#ifndef _IES_AUTO_MIBS_HANDLE_URI_FIXED_VALUE_C_
#define _IES_AUTO_MIBS_HANDLE_URI_FIXED_VALUE_C_

/*-------------------------------------------------------------------+
 * Function           : ies_auto_mibs_handle_uri_fixed_value
 *
 * Description        :


+-------------------------------------------------------------------*/
ies_handle_t 
ies_auto_mibs_handle_uri_fixed_value
(
    struct ies_auto_mibs_entry   *entry, 
    char                         *sys_cmd_buf,
    int                           sys_cmd_buf_len
)
{
    ies_handle_t                  ret = IES_ERR;

    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "eventLog/logClear") )
    {
        snprintf(sys_cmd_buf, sys_cmd_buf_len, "%d", 2);
    }
    else
    {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__ );
        goto out;
    }
    ret = IES_NOERR;
out:
    return ret;
}

#endif // _IES_AUTO_MIBS_HANDLE_URI_FIXED_VALUE_C_
